class TestExceptionHierarchy:
    """Verify exception taxonomy and error code integrity."""

    def test_base_exception_attributes(self):
        """Base error must carry message and machine-readable code."""
        err = MathSolverError("test failure", "ERR_999")
        assert str(err) == "test failure"
        assert err.code == "ERR_999"

    def test_all_exceptions_derive_from_base(self):
        """Every mesh exception must inherit from MathSolverError."""
        exceptions = [
            SyntaxErrorMesh(),
            DomainErrorMesh(),
            ConvergenceErrorMesh(),
            ComplexityErrorMesh(),
            ParameterErrorMesh(),
        ]
        for exc in exceptions:
            assert isinstance(exc, MathSolverError)

    def test_error_codes_unique_and_sequential(self):
        """Error codes must be unique and follow ERR_00X pattern."""
        codes = [
            SyntaxErrorMesh().code,
            DomainErrorMesh().code,
            ConvergenceErrorMesh().code,
            ComplexityErrorMesh().code,
            ParameterErrorMesh().code,
        ]
        assert len(codes) == len(set(codes)), "Duplicate error codes detected"
        assert all(code.startswith("ERR_") for code in codes)

    def test_custom_error_messages(self):
        """Custom messages must propagate through constructor."""
        custom_msg = "Custom domain violation"
        err = DomainErrorMesh(custom_msg)
        assert str(err) == custom_msg
        assert err.code == "ERR_002"

