class TestSymbolicOperations:
    """Validate symbolic manipulation: simplify, expand, factor."""

    @pytest.mark.parametrize(
        "expression,expected",
        [
            ("x**2 + 2*x + 1", "(x + 1)**2"),
            ("x**2 - 1", "(x - 1)*(x + 1)"),
            ("x**3 - 8", "(x - 2)*(x**2 + 2*x + 4)"),
        ],
    )
    def test_factorization(self, engine_default, expression, expected):
        """Factorization must produce canonical symbolic form."""
        result = engine_default.factor(expression)
        assert simplify(result.expression - sympify(expected)) == 0

    @pytest.mark.parametrize(
        "expression,expected",
        [
            ("(x + 1)**2", "x**2 + 2*x + 1"),
            ("(x - 2)*(x + 2)", "x**2 - 4"),
        ],
    )
    def test_expansion(self, engine_default, expression, expected):
        """Expansion must distribute products correctly."""
        result = engine_default.expand(expression)
        assert simplify(result.expression - sympify(expected)) == 0

    def test_simplification_identity(self, engine_default):
        """Simplification must preserve mathematical equivalence."""
        original = "sin(x)**2 + cos(x)**2"
        result = engine_default.simplify(original)
        assert simplify(result.expression - 1) == 0

    def test_simplification_returns_simpler_form(self, engine_default):
        """Simplified expression must be structurally simpler."""
        original = "x**2 + 2*x + 1"
        result = engine_default.simplify(original)
        assert len(str(result.expression)) <= len(original)

