class TestEquationSolving:
    """Validate root finding and system solving."""

    @pytest.mark.parametrize(
        "equation,var,expected_roots",
        [
            ("x**2 - 4", "x", [-2, 2]),
            ("x**2 + 3*x - 4", "x", [-4, 1]),
            ("x**3 - 6*x**2 + 11*x - 6", "x", [1, 2, 3]),
        ],
    )
    def test_polynomial_roots(self, engine_default, equation, var, expected_roots):
        """Polynomial roots must match expected set."""
        result = engine_default.solve_equation(equation, var)
        roots = sorted(float(r) for r in result.solutions)
        expected = sorted(expected_roots)
        assert len(roots) == len(expected)
        for got, want in zip(roots, expected):
            assert abs(got - want) < 1e-10

    def test_quadratic_discriminant_zero(self, engine_default):
        """Double root must be detected."""
        result = engine_default.solve_equation("x**2 - 2*x + 1", "x")
        assert len(result.solutions) == 1
        assert abs(float(result.solutions[0]) - 1.0) < 1e-10

    def test_linear_equation(self, engine_default):
        """Linear equation must yield single root."""
        result = engine_default.solve_equation("3*x - 7", "x")
        assert len(result.solutions) == 1
        assert abs(float(result.solutions[0]) - 7.0 / 3.0) < 1e-10

    def test_system_of_equations(self, engine_default):
        """Linear system must be solved correctly."""
        system = ["x + y - 3", "x - y - 1"]
        result = engine_default.solve_system(system, ["x", "y"])
        assert len(result.solutions) == 1
        sol = result.solutions[0]
        assert abs(float(sol["x"]) - 2.0) < 1e-10
        assert abs(float(sol["y"]) - 1.0) < 1e-10

    def test_transcendental_equation_numerical(self, engine_default):
        """Transcendental equations must use numerical fallback."""
        result = engine_default.solve_equation("cos(x) - x", "x")
        assert len(result.solutions) >= 1
        # Verify solution satisfies equation
        x_val = float(result.solutions[0])
        assert abs(math.cos(x_val) - x_val) < 1e-6

