    def test_high_precision_evaluation(self, engine_high_precision):
        """High-precision engine must achieve 50-digit accuracy."""
        result = engine_high_precision.evaluate("sqrt(2)", {})
        assert mpmath.mpf(str(result.value)) - mpmath.sqrt(2) < mpmath.mpf("1e-45")

    def test_numerical_stability_cancellation(self, engine_default):
        """Catastrophic cancellation must be handled gracefully."""
        # x - sin(x) for small x suffers from cancellation
        result = engine_default.evaluate("x - sin(x)", {"x": 1e-8})
        # True value ~ x^3/6 = 1.666e-25
        assert abs(result.value - (1e-8)**3 / 6.0) < 1e-30

    def test_numerical_derivative(self, engine_default):
        """Numerical differentiation must approximate analytical derivative."""
        result = engine_default.numerical_derivative("sin(x)", "x", 0.5)
