    def test_numerical_integration_adaptive(self, engine_default):
        """Adaptive quadrature must handle oscillatory integrands."""
        result = engine_default.numerical_integrate("sin(100*x)", "x", 0, math.pi)
        # Integral of sin(100x) over [0, pi] = (1 - cos(100*pi))/100 ≈ 0.02
        assert abs(result.value - 0.02) < 1e-4

