class TestPropertyBased:
    """Mathematical invariants that must hold for arbitrary inputs."""

    @pytest.mark.parametrize("n", [0, 1, 2, 3, 5, 10, 20])
    def test_polynomial_derivative_integral_roundtrip(self, engine_default, n):
        """d/dx ∫ f(x) dx = f(x) for polynomial of degree n."""
        # Construct polynomial with random coefficients
        coeffs = [i + 1 for i in range(n + 1)]
        poly = " + ".join(f"{c}*x**{i}" for i, c in enumerate(coeffs))
        integral = engine_default.integrate(poly, "x")
        derivative = engine_default.differentiate(str(integral.expression), "x")
        assert simplify(derivative.expression - sympify(poly)) == 0

    @pytest.mark.parametrize("a,b", [(0, 1), (-1, 1), (2, 5), (-3, -1)])
    def test_definite_integral_additivity(self, engine_default, a, b):
        """∫_a^b f + ∫_b^c f = ∫_a^c f for midpoint c."""
        c = (a + b) / 2
        f = "x**2"
        left = engine_default.integrate_definite(f, "x", a, c).value
        right = engine_default.integrate_definite(f, "x", c, b).value
        total = engine_default.integrate_definite(f, "x", a, b).value
        assert abs((left + right) - total) < 1e-8

    @pytest.mark.parametrize("x_val", [0.0, 0.5, 1.0, 2.0, 10.0])
    def test_exp_log_inverse(self, engine_default, x_val):
        """log(exp(x)) = x for positive x."""
        result = engine_default.evaluate("log(exp(x))", {"x": x_val})
        assert abs(result.value - x_val) < 1e-10

    @pytest.mark.parametrize("x_val", [-10.0, -1.0, 0.0, 1.0, 10.0])
    def test_sin_cos_identity(self, engine_default, x_val):
        """sin^2(x) + cos^2(x) = 1 for all x."""
        result = engine_default.evaluate("sin(x)**2 + cos(x)**2", {"x": x_val})
        assert abs(result.value - 1.0) < 1e-10

    @pytest.mark.parametrize("x_val", [0.5, 1.0, 2.0, 3.0])
    def test_derivative_linearity(self, engine_default, x_val):
        """d/dx (f + g) = df/dx + dg/dx."""
        f = "x**3"
        g = "sin(x)"
        sum_deriv = engine_default.differentiate(f"({f}) + ({g})", "x")
        f_deriv = engine_default.differentiate(f, "x")
        g_deriv = engine_default.differentiate(g, "x")
        combined = engine_default.evaluate(
            str(sum_deriv.expression), {"x": x_val}
        ).value
        expected = engine_default.evaluate(
            f"({f_deriv.expression}) + ({g_deriv.expression})", {"x": x_val}
        ).value
        assert abs(combined - expected) < 1e-8

