class TestPerformance:
    """Validate computational efficiency and timeout enforcement."""

    def test_quick_operation_latency(self, engine_default):
        """Simple operations must complete in under 100ms."""
        start = time.perf_counter()
        engine_default.simplify("x**2 + 2*x + 1")
        elapsed = time.perf_counter() - start
        assert elapsed < 0.1, f"Operation took {elapsed:.3f}s"

    def test_large_polynomial_factorization(self, engine_default):
        """High-degree polynomial must factor within timeout."""
        # (x+1)^10 expanded
        expr = str(sympify("(x+1)**10").expand())
        start = time.perf_counter()
        result = engine_default.factor(expr)
        elapsed = time.perf_counter() - start
        assert elapsed < 5.0, f"Factorization took {elapsed:.3f}s"
        assert result is not None

    def test_timeout_enforcement(self):
        """Excessively complex operations must raise ConvergenceErrorMesh."""
        engine = MathSolverEngine(
            config=SolverConfig(timeout_seconds=0.001, max_depth=5)
        )
        with pytest.raises(ConvergenceErrorMesh):
            engine.integrate("exp(x**10)", "x")

    def test_many_sequential_operations(self, engine_default):
        """Engine must handle 1000 sequential operations without degradation."""
        start = time.perf_counter()
        for i in range(1000):
            engine_default.evaluate("x**2", {"x": float(i)})
        elapsed = time.perf_counter() - start
        assert elapsed < 10.0, f"1000 ops took {elapsed:.3f}s"

    def test_concurrent_engine_instances(self):
        """Multiple engine instances must operate independently."""
        engines = [MathSolverEngine() for _ in range(10)]
        results = []
        for i, eng in enumerate(engines):
            results.append(eng.evaluate("x + 1", {"x": float(i)}).value)
        assert results == [float(i) + 1 for i in range(10)]

