class TestIntegration:
    """End-to-end workflows combining multiple operations."""

    def test_full_workflow_polynomial_analysis(self, engine_default):
        """Complete analysis: factor → differentiate → integrate → evaluate."""
        expr = "x**2 - 5*x + 6"

        # Factor
        factored = engine_default.factor(expr)
        assert str(factored.expression) == "(x - 2)*(x - 3)"

        # Differentiate
        derivative = engine_default.differentiate(expr, "x")
        assert str(derivative.expression) == "2*x - 5"

        # Integrate
        integral = engine_default.integrate(expr, "x")
        # Verify by differentiation
        check = engine_default.differentiate(str(integral.expression), "x")
        assert simplify(check.expression - sympify(expr)) == 0

        # Evaluate at point
        value = engine_default.evaluate(expr, {"x": 4.0})
        assert value.value == 2.0

    def test_physics_kinematics(self, engine_default):
        """Position → velocity → acceleration workflow."""
        position = "5*t**3 - 2*t**2 + 10*t"

        velocity = engine_default.differentiate(position, "t")
        acceleration = engine_default.differentiate(str(velocity.expression), "t")

        # At t=2: v = 15*4 - 4*2 + 10 = 62, a = 30*2 - 4 = 56
        v_at_2 = engine_default.evaluate(str(velocity.expression), {"t": 2.0})
        a_at_2 = engine_default.evaluate(str(acceleration.expression), {"t": 2.0})

        assert abs(v_at_2.value - 62.0) < 1e-10
        assert abs(a_at_2.value - 56.0) < 1e-10

    def test_optimization_critical_points(self, engine_default):
        """Find critical points of f(x) = x^3 - 3x^2 + 2."""
        f = "x**3 - 3*x**2 + 2"
        f_prime = engine_default.differentiate(f, "x")
        critical = engine_default.solve_equation(str(f_prime.expression), "x")

        roots = sorted(float(r) for r in critical.solutions)
        assert len(roots) == 2
        assert abs(roots[0] - 0.0) < 1e-10
        assert abs(roots[1] - 2.0) < 1e-10

    def test_regression_known_bug_fix(self, engine_default):
        """Regression: negative coefficients in factorization."""
        result = engine_default.factor("-x**2 + 4")
        assert simplify(result.expression - sympify("-(x - 2)*(x + 2)")) == 0

    def test_regression_complex_roots(self, engine_default):
        """Regression: quadratic with complex roots."""
        result = engine_default.solve_equation("x**2 + 1", "x")
        assert len(result.solutions) == 2
        # Solutions should be ±i
        for sol in result.solutions:
            assert abs(complex(sol)**2 + 1) < 1e-10

