def _verify_imports():
    """Ensure all required modules are importable at test time."""
    import sympy
    import mpmath
    assert sympy.__version__ >= "1.9"
    assert mpmath.__version__ >= "1.2"

def pytest_configure(config):
    """Configure pytest markers for test categorization."""
    config.addinivalue_line(
        "markers", "slow: marks tests as slow (deselect with '-m \"not slow\"')"
    )
    config.addinivalue_line(
        "markers", "property: property-based tests using mathematical invariants"
    )

# Mark slow tests
TestPerformance.test_large_polynomial_factorization = pytest.mark.slow(
    TestPerformance.test_large_polynomial_factorization
)
